class TrieNode {
  constructor(){ this.next = new Map(); this.cnt = 0; }
}
class Trie {
  constructor(){ this.root = new TrieNode(); }
  insert(word){ let node=this.root; for(let ch of word){ if(!node.next.has(ch)) node.next.set(ch,new TrieNode()); node = node.next.get(ch); node.cnt++; } }
  erase(word){ let stack=[]; let node=this.root; for(let ch of word){ if(!node.next.has(ch)) return; node = node.next.get(ch); stack.push([node,ch]); } // decrement
